#!/usr/bin/env bash
# Hors Boîte — projet complet v0.4 : Permut' seul (annonces style petites annonces + matching intelligent), desktop responsive mobile
# Usage : bash install-horsboite-v4.sh  (à la racine : écrase les fichiers du projet)
set -e

# Nettoyage des anciens modules
rm -rf "app/(app)/ecoute" "app/(app)/apres" "app/(app)/points" components/SideNav.tsx components/TabBar.tsx components/Urgence.tsx components/PageHeader.tsx "app/(app)/permut/Liste.tsx" "app/(app)/permut/[id]" "app/(app)/profil/Form.tsx" "app/(app)/accueil/page.tsx" 2>/dev/null || true

cat > ".env.example" << 'HB_EOF'
# Supabase (Project settings > API)
NEXT_PUBLIC_SUPABASE_URL=https://xxxx.supabase.co
NEXT_PUBLIC_SUPABASE_ANON_KEY=eyJ...
SUPABASE_SERVICE_ROLE_KEY=eyJ...

# Secrets applicatifs (générer avec : openssl rand -hex 32)
IDENTITIES_KEY=            # clé AES-256 de chiffrement des identités (64 hex)
MATRICULE_PEPPER=          # poivre du hachage matricule (64 hex)
CRON_SECRET=               # protège /api/cron/matching

# Resend
RESEND_API_KEY=re_...
EMAIL_FROM="Hors Boîte <noreply@horsboite.fr>"

# Stripe
STRIPE_SECRET_KEY=sk_live_...
STRIPE_WEBHOOK_SECRET=whsec_...
STRIPE_PRICE_ID=price_...        # abonnement 9,99 €/mois
STRIPE_BOOST_PRICE_ID=price_...  # mise en avant d'annonce 4,99 €, paiement unique

# Site
NEXT_PUBLIC_SITE_URL=https://horsboite.fr
HB_EOF

