cat > "app/api/correspondances/route.ts" << 'HB_EOF'
import { NextRequest, NextResponse } from 'next/server';
import { currentUser, supabaseAdmin, supabaseServer } from '@/lib/supabase-server';
import { decrypt } from '@/lib/crypto';

export const runtime = 'nodejs';

/** POST { id, action:'accepter'|'refuser'|'ignorer'|'reveler' } */
export async function POST(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: 'non connecté' }, { status: 401 });
  const { id, action } = await req.json();
  const sb = supabaseServer();
  const admin = supabaseAdmin();

  const { data: profil } = await sb.from('profils').select('premium_jusqua').eq('id', user.id).single();
  const premium = !!profil?.premium_jusqua && new Date(profil.premium_jusqua) > new Date();

  if (action === 'ignorer') {
    await sb.from('correspondances_ignorees').upsert({ profil_id: user.id, correspondance_id: id });
    return NextResponse.json({ ok: true });
  }
  if (action === 'accepter' || action === 'refuser') {
    if (!premium) return NextResponse.json({ ok: false, paywall: true }, { status: 402 });
    await sb.from('correspondance_membres').update({ reponse: action === 'accepter' ? 'accepte' : 'refuse' })
      .eq('correspondance_id', id).eq('profil_id', user.id);
    const { data: membres } = await admin.from('correspondance_membres').select('reponse').eq('correspondance_id', id);
    const statut = membres?.some(m => m.reponse === 'refuse') ? 'refusee' : membres?.every(m => m.reponse === 'accepte') ? 'confirmee' : 'en_cours';
    await admin.from('correspondances').update({ statut, updated_at: new Date().toISOString() }).eq('id', id);
    return NextResponse.json({ ok: true, statut });
  }
  if (action === 'reveler') {
    const { data: membres } = await admin.from('correspondance_membres').select('profil_id, position, reponse').eq('correspondance_id', id);
    if (!membres?.some(m => m.profil_id === user.id)) return NextResponse.json({ error: 'non membre' }, { status: 403 });
    if (!membres.every(m => m.reponse === 'accepte')) return NextResponse.json({ error: 'cycle non confirmé' }, { status: 409 });
    await admin.from('journal_identites').insert({ profil_id: user.id, par_fonction: 'reveler_identites', correspondance_id: id });
    const autres = membres.filter(m => m.profil_id !== user.id);
    const { data: idents } = await admin.from('identites').select('profil_id, nom_enc, prenom_enc, telephone_enc, mail_pro_enc').in('profil_id', autres.map(a => a.profil_id));
    return NextResponse.json({
      ok: true,
      agents: (idents ?? []).map(i => ({
        position: autres.find(a => a.profil_id === i.profil_id)!.position,
        prenom: decrypt(i.prenom_enc), nom: decrypt(i.nom_enc).slice(0, 1) + '.',
        telephone: i.telephone_enc ? decrypt(i.telephone_enc) : null, mail_pro: decrypt(i.mail_pro_enc),
      })),
    });
  }
  return NextResponse.json({ error: 'action inconnue' }, { status: 400 });
}
HB_EOF

mkdir -p "app/api/cron/matching"
cat > "app/api/cron/matching/route.ts" << 'HB_EOF'
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabase-server';
import { Agent, construireGraphe, scorer, trouverCycles } from '@/lib/matching';

export const runtime = 'nodejs';
export const maxDuration = 60;

/** Appelé par Vercel Cron toutes les heures. Protégé par CRON_SECRET. */
export async function GET(req: NextRequest) {
  if (req.headers.get('authorization') !== `Bearer ${process.env.CRON_SECRET}`) {
    return NextResponse.json({ error: 'interdit' }, { status: 401 });
  }
  const admin = supabaseAdmin();
  const { data: profils } = await admin
    .from('profils')
    .select('id, institution, corps, grade, service_id, type_service, anciennete_poste_mois, depart_des, accepte_cycles, accepte_souhait_2_3, accepte_changer_service, premium_jusqua, services(departement), souhaits(rang, service_id, departement, contrainte_type_service)')
    .or('verifie_carte.eq.true,verifie_mail_pro.eq.true');

  const agents: Agent[] = (profils ?? []).map((p: any) => ({
    id: p.id, institution: p.institution, corps: p.corps, grade: p.grade, service_id: p.service_id,
    departement: p.services?.departement ?? null, type_service: p.type_service,
    anciennete_poste_mois: p.anciennete_poste_mois, depart_des: p.depart_des,
    accepte_cycles: p.accepte_cycles, accepte_souhait_2_3: p.accepte_souhait_2_3, accepte_changer_service: p.accepte_changer_service,
    premium: !!p.premium_jusqua && new Date(p.premium_jusqua) > new Date(),
    souhaits: p.souhaits ?? [],
  }));
  const map = new Map(agents.map(a => [a.id, a]));
  const cycles = trouverCycles(construireGraphe(agents), map, 4);

  let crees = 0;
  for (const c of cycles) {
    const signature = [...c.ids].sort().join('|');
    const { score, detail } = scorer(c, map);
    if (score < 40) continue;
    const { data: corr, error } = await admin.from('correspondances').insert({
      institution: map.get(c.ids[0])!.institution,
      type: c.ids.length === 2 ? 'directe' : c.ids.length === 3 ? 'cycle3' : 'cycle4',
      score, detail, signature,
    }).select('id').single();
    if (error || !corr) continue; // signature déjà connue
    const now = Date.now();
    const membres = c.ids.map((id, i) => {
      const suivant = map.get(c.ids[(i + 1) % c.ids.length])!;
      const a = map.get(id)!;
      return {
        correspondance_id: corr.id, profil_id: id, position: i + 1, vers_service_id: suivant.service_id,
        // Premium : notifié tout de suite ; gratuit : 48 h plus tard
        notifie_le: new Date(now + (a.premium ? 0 : 48 * 3600e3)).toISOString(),
      };
    });
    await admin.from('correspondance_membres').insert(membres);
    crees++;
  }
  return NextResponse.json({ agents: agents.length, cycles: cycles.length, crees });
}
HB_EOF

