export const PROJ = { minx: -3.300949299373342, miny: -51.089, sc: 34.40942644115323, k: 0.688354575693754 };
export const projeter = (lng: number, lat: number) => [
  Math.round(((lng * PROJ.k - PROJ.minx) * PROJ.sc) * 10) / 10,
  Math.round(((-lat - PROJ.miny) * PROJ.sc) * 10) / 10,
] as const;
